# ------------------------------------------------------------------------------------------------ calculation drills (seeded, auto-graded)
def _fmt(x, d=3): return f"{x:.{d}f}"

def drill(kind, seed=1):
    """Return dict(kind, q, opts, ans, why, lesson, answer). The correct option is the exact computed value; distractors are the typical errors named in `why`."""
    rng = random.Random(f"{kind}:{seed}")
    if kind == "se_from_ci":
        lo, hi, n = round(rng.uniform(1, 4), 1), 0.0, rng.choice([9, 16, 25, 36]); hi = round(lo + rng.uniform(2, 5), 1)
        se = (hi - lo) / (2 * 1.96); sd = se * math.sqrt(n); ok = sd
        return _mc(kind, f"A study reports a mean with 95% CI {lo} to {hi} (n = {n}, large-sample 1.96 rule). What is the SD?", ok, [se, (hi - lo) / 2 * math.sqrt(n), (hi - lo) * math.sqrt(n)],
                   "SE = (U - L)/(2 x 1.96); SD = SE x sqrt(n). Wrong options: SE itself, half-width x sqrt(n) (forgot 1.96), full width x sqrt(n).", 18)
    if kind == "hedges_g":
        n = rng.choice([8, 10, 12, 15, 20]); m1, m2, sd = round(rng.uniform(11, 14), 1), round(rng.uniform(9, 11), 1), round(rng.uniform(1.5, 3), 1)
        g, v, j = S.smd(m1, sd, n, m2, sd, n); d = (m1 - m2) / sd
        return _mc(kind, f"Two groups of n = {n}; means {m1} and {m2}; common SD = {sd}. What is Hedges' g (exact small-sample correction)?", g, [d, d * 1.1, (m1 - m2) / (sd / math.sqrt(n))],
                   "g = J x d with J from the gamma function; d = (m1 - m2)/SD. Wrong options: uncorrected d, d inflated by 10%, difference divided by SE.", 27)
    if kind == "pooled_common":
        k = 3; y = [round(rng.uniform(0.1, 0.9), 2) for _ in range(k)]; v = [round(rng.choice([0.02, 0.04, 0.08, 0.16]), 2) for _ in range(k)]; r = S.meta_analyze(y, v, "common")
        return _mc(kind, f"Three studies give effects {y} with variances {v}. What is the common-effect (inverse-variance) pooled estimate?", r.est, [float(np.mean(y)), float(np.median(y)), float(np.average(y, weights=np.sqrt(1 / np.array(v))))],
                   "Weights are 1/variance. Wrong options: unweighted mean, median, weights 1/SD.", 32)
    if kind == "i2":
        y, v = [0.1, 0.3, round(rng.uniform(0.4, 0.7), 2), round(rng.uniform(0.7, 1.1), 2)], [0.02, 0.03, 0.025, 0.04]; r = S.meta_analyze(y, v, "common")
        return _mc(kind, f"Four studies with effects {y} and variances {v}. What is I² (Q-based, in %)?", r.I2, [r.Q, 100 * r.Q_p, max(0, 100 * (1 - 1 / r.H2) * 0.5)],
                   f"I² = max(0, (Q - df)/Q) x 100 with Q = {r.Q:.2f} and df = 3. Wrong options: Q itself, the p-value x 100, half of I².", 35, d=1)
    if kind == "nnt":
        pc = rng.choice([0.05, 0.1, 0.2, 0.3]); rr = rng.choice([0.5, 0.6, 0.75, 0.8]); arr = pc * (1 - rr); nnt = 1 / arr
        return _mc(kind, f"Control-group risk is {int(pc*100)}% and the risk ratio is {rr}. What is the number needed to treat?", nnt, [1 / (1 - rr), 1 / pc, 1 / (rr * (1 - pc))],
                   "ARR = p_c (1 - RR); NNT = 1/ARR. Wrong options: 1/(1-RR), 1/p_c, 1/(RR x (1 - p_c)).", 57, d=1)
    if kind == "lnrr":
        m1, m2 = rng.choice([12, 15, 18, 24]), rng.choice([8, 10, 12, 16]); y = math.log(m1 / m2)
        return _mc(kind, f"Treated mean lifespan {m1} d, control {m2} d. What is the log response ratio (natural log)?", y, [m1 / m2, m1 - m2, math.log10(m1 / m2)],
                   "lnRR = ln(treated/control). Wrong options: the ratio, the raw difference, the base-10 log.", 27)
    if kind == "fisher_z":
        r_, n = rng.choice([0.2, 0.3, 0.5, 0.6]), rng.choice([20, 28, 40, 53]); z, v = S.fisher_z(r_, n)
        return _mc(kind, f"A correlation r = {r_} in n = {n}. What is the variance of Fisher's z?", v, [1 / n, 1 / (n - 1), (1 - r_ ** 2) ** 2 / (n - 1)],
                   "Var(z) = 1/(n - 3). Wrong options: 1/n, 1/(n - 1), the raw-r variance.", 29, d=4)
    if kind == "design_effect":
        m, icc, n = rng.choice([5, 8, 10, 20]), rng.choice([0.05, 0.1, 0.2]), rng.choice([60, 100, 160]); de = A.design_effect(m, icc)
        return _mc(kind, f"{n} observations in clusters of {m}; ICC = {icc}. What is the effective sample size?", n / de, [n * de, n / m, n / (1 + icc)],
                   "DEFF = 1 + (m - 1) ICC; n_eff = n/DEFF. Wrong options: n x DEFF, number of clusters, n/(1 + ICC).", 85, d=1)
    if kind == "logit":
        n = rng.choice([40, 80, 120]); x = rng.choice([4, 8, 12, 20]); y, v = A.proportion_es(x, n, "PLO")
        return _mc(kind, f"{x} of {n} animals carry a phenotype. What is the logit of the proportion?", y, [x / n, math.log(x / n), -y],
                   "logit = ln(p/(1-p)). Wrong options: the proportion, ln p, the sign-flipped logit.", 47)
    raise ValueError("unknown drill kind")

DRILLS = ["se_from_ci", "hedges_g", "pooled_common", "i2", "nnt", "lnrr", "fisher_z", "design_effect", "logit"]

def _mc(kind, q, correct, wrong, why, lesson, d=3):
    vals = [round(correct, d)];
    for w in wrong:
        w = round(float(w), d)
        if w not in vals: vals.append(w)
    while len(vals) < 4: vals.append(round(correct * (1 + 0.1 * len(vals)) + 0.01 * len(vals), d))
    opts = [_fmt(v, d) for v in vals[:4]]; order = list(range(4)); random.Random(f"{kind}:{q}").shuffle(order)
    return dict(kind=kind, q=q, opts=[opts[i] for i in order], ans=order.index(0), why=why, lesson=lesson, answer=float(round(correct, d)), numeric=True)


