def method_item(i, rng_seed=1):
    it = METHOD_ITEMS[i]; order = list(range(len(it["opts"]))); random.Random(f"{it['id']}:{rng_seed}").shuffle(order)
    return dict(kind="method", id=it["id"], q=it["q"], opts=[it["opts"][j] for j in order], ans=order.index(it["ans"]), why=it["why"], lesson=it["lessons"][0], lessons=it["lessons"])


# ------------------------------------------------------------------------------------------------ interpretation bank (numbers computed live)
def _bcg():
    ys, vs = zip(*[S.log_risk_ratio(a, a + b, c, c + d) for a, b, c, d in DS.BCG]); return list(ys), list(vs)

def interpretation_items():
    """Statements about the BCG REML analysis; each is classified 'supported' / 'not supported' with the number that decides it. Computed from code."""
    y, v = _bcg(); r = S.meta_analyze(y, v, "random", "REML", hksj=True); eg = A.egger_test(y, v); rr = math.exp(r.est); pi = r.pred_int; items = []
    add = lambda q, ok, why, lesson: items.append(dict(kind="interpretation", q=f"Statement: {q}", opts=["Supported by these results", "Not supported / over-reach"], ans=0 if ok else 1, why=why, lesson=lesson))
    add(f"The pooled risk ratio is below 1 (RR = {rr:.2f}), i.e. on average the vaccine group had lower TB risk in these trials.", rr < 1, f"Pooled lnRR {r.est:.3f}; HKSJ CI {math.exp(r.ci[0]):.2f}-{math.exp(r.ci[1]):.2f} excludes 1.", 35)
    add(f"Between-trial heterogeneity is substantial (I² ≈ {r.I2:.0f}%).", r.I2 > 75, f"Q-based I² = {r.I2:.1f}%; heterogeneity is high.", 35)
    add("The vaccine works in every setting, so a new trial would certainly show a benefit.", pi[0] > 0 or pi[1] < 0, f"The 95% prediction interval is RR {math.exp(pi[0]):.2f}-{math.exp(pi[1]):.2f}: it includes 1, so a new trial could show no benefit.", 35)
    add("Because the confidence interval excludes 1, there is no need to examine why results differ between trials.", False, "Heterogeneity (and moderators such as latitude) must be explored; significance of the mean does not explain differences.", 36)
    add(f"The Egger test (p = {eg['p']:.2f}) proves there is no publication bias.", False, "Absence of significance with k = 13 does not prove absence of bias; the test has low power.", 36)
    add("The between-study variance τ² is zero, so a common-effect model would have been equivalent.", r.tau2 < 1e-6, f"τ² = {r.tau2:.3f} (not zero).", 34)
    add("The Hartung-Knapp interval is wider than the Wald interval here, reflecting small-k uncertainty.", (r.ci[1] - r.ci[0]) > 2 * 1.96 * S.meta_analyze(y, v, "random", "REML").se, "HKSJ half-width exceeds the Wald half-width in this dataset.", 34)
    add("Latitude (a trial-level moderator) explaining part of the heterogeneity is a causal effect of latitude on vaccine efficacy.", False, "Meta-regression associations across trials are observational and ecological, not causal.", 37)
    return items


# ------------------------------------------------------------------------------------------------ final comprehensive assessment
SECTIONS = ["Concepts (lessons)", "Calculation", "Method selection", "Interpretation"]

def final_exam(seed=1, per_part=2, n_calc=9, n_method=12, n_interp=8):
    """Stratified, deterministic, answer-keyed: `per_part` lesson questions from every curriculum part (18 parts), plus calculation drills, method-selection items and interpretation items."""
    L = lessons.load(); rng = random.Random(f"final:{seed}"); qs = []
    for part in sorted({m["part"] for m in curriculum.MODULES}):
        mods = [m["id"] for m in curriculum.MODULES if m["part"] == part and m["id"] in L]; rng.shuffle(mods)
        for mid in mods[:per_part]:
            e = AS.exam([mid], 1, seed=rng.randint(1, 10 ** 6))[0]; qs.append(dict(e, section=SECTIONS[0], part=part, kind="lesson"))
    kinds = list(DRILLS); rng.shuffle(kinds)
    for k in kinds[:n_calc]: d = drill(k, rng.randint(1, 10 ** 6)); qs.append(dict(d, module=d["lesson"], qid=f"drill:{k}", section=SECTIONS[1], part=None))
    idx = list(range(len(METHOD_ITEMS))); rng.shuffle(idx)
    for i in idx[:n_method]: d = method_item(i, rng.randint(1, 10 ** 6)); qs.append(dict(d, module=d["lesson"], qid=f"method:{d['id']}", section=SECTIONS[2], part=None))
    it = interpretation_items(); rng.shuffle(it)
    for j, d in enumerate(it[:n_interp]): qs.append(dict(d, module=d["lesson"], qid=f"interp:{j}", section=SECTIONS[3], part=None))
    rng.shuffle(qs); return qs

def score_final(qs, answers, mastery=0.8):
    if len(answers) != len(qs): raise ValueError("One answer (or None) per question.")
    sec, parts, mods = {}, {}, {}
    for q, a in zip(qs, answers):
        ok = int(a == q["ans"]); s = sec.setdefault(q["section"], [0, 0]); s[0] += ok; s[1] += 1
        if q.get("part"): p = parts.setdefault(q["part"], [0, 0]); p[0] += ok; p[1] += 1
        m = mods.setdefault(q["module"], [0, 0]); m[0] += ok; m[1] += 1
    c = sum(v[0] for v in sec.values()); t = len(qs)
    weak_sections = sorted(k for k, (a, n) in sec.items() if n and a / n < mastery)
    return dict(total=t, correct=c, pct=c / t if t else 0.0, by_section={k: tuple(v) for k, v in sec.items()}, by_part={curriculum.PARTS[k]: tuple(v) for k, v in parts.items()},
                weak_sections=weak_sections, weak_modules=sorted(m for m, (a, n) in mods.items() if a < n), passed_internal_benchmark=bool(t and c / t >= mastery and not weak_sections),
                note="Self-assessment against an internal 80% benchmark in every section; not a validated test.")


