RUBRIC = [
 ("protocol_before_search", "Protocol (question, eligibility, outcomes, analysis plan) written BEFORE searching/screening", True),
 ("search_records", "Searches logged with database, date, exact query and counts (reproducible)", False),
 ("two_person_screening", "Independent second screener and agreement statistic (kappa) reported", False),
 ("extraction_verified", "Extracted values carry source/page and are verified by a second person", True),
 ("rob_per_outcome", "Risk of bias assessed per outcome with a named tool and support text", False),
 ("effect_sizes_traceable", "Effect sizes computed from extracted values with units/conversions documented", False),
 ("model_prespecified", "Model, τ² estimator and CI method pre-specified; deviations logged", False),
 ("sensitivity_analyses", "Sensitivity analyses reported (estimator, leave-one-out, dependence handling)", False),
 ("bias_analyses", "Small-study/publication-bias analyses reported with their warnings", False),
 ("certainty_rated", "Certainty of evidence rated per outcome with reasons", False),
 ("numbers_traceable", "Every manuscript number traces to a stored, verified result", True),
 ("limitations_stated", "Limitations and uncertainty stated honestly", False),
 ("deviations_logged", "Deviations from the protocol logged and reported", False),
]
BENCHMARK = 20

def capstone_status(items):
    """items: dict key -> {score, note} (Store.capstone_items()). Returns total, max, blockers (0 on a blocker item), ready flag."""
    total = sum(int(items.get(k, {}).get("score", 0)) for k, _, _ in RUBRIC); mx = 2 * len(RUBRIC)
    blockers = [lab for k, lab, b in RUBRIC if b and int(items.get(k, {}).get("score", 0)) == 0]
    missing = [lab for k, lab, _ in RUBRIC if k not in items]
    return dict(total=total, max=mx, pct=total / mx, blockers=blockers, unscored=missing, ready_for_expert_review=bool(total >= BENCHMARK and not blockers),
                note="Internal self-check (13 items x 0-2). A score of 20 or more with no blocker means 'ready to ask experts to review', not 'competent'.")


# ------------------------------------------------------------------------------------------------ practice datasets and formula sheets
def practice_datasets():
    """name -> (csv text, provenance text). Published example data come from the R package metadat (provenance cited); SIMULATED data are labelled."""
    out = {}
    def w(rows, cols): b = io.StringIO(); cw = csv.writer(b); cw.writerow(cols); cw.writerows(rows); return b.getvalue()
    out["bcg_trials.csv"] = (w([(i + 1, a, b, c, d, DS.BCG_ABLAT[i], DS.BCG_ALLOC[i]) for i, (a, b, c, d) in enumerate(DS.BCG)], ["trial", "tpos", "tneg", "cpos", "cneg", "ablat", "alloc"]), "Published example (metadat::dat.bcg; source: Colditz et al. 1994, JAMA). For teaching.")
    out["smoking_cessation_network.csv"] = (w(DS.HASSELBLAD, ["study", "treatment", "events", "n"]), "Published example (metadat::dat.hasselblad1998; Hasselblad 1998). Multi-arm network meta-analysis.")
    out["periodontal_two_outcomes.csv"] = (w(list(zip(DS.BERKEY_TRIAL, DS.BERKEY_OUTCOME, DS.BERKEY_YI)), ["trial", "outcome", "yi"]), "Published example (metadat::dat.berkey1998; Berkey et al. 1998). Within-trial covariances are in metalab.datasets.BERKEY_V.")
    out["konstantopoulos_schools.csv"] = (w(list(zip(DS.KON_DISTRICT, DS.KON_YI, DS.KON_VI)), ["district", "yi", "vi"]), "Published example (metadat::dat.konstantopoulos2011; Konstantopoulos 2011). Three-level/CR2 teaching data.")
    out["dta_synthetic.csv"] = (w([(i + 1, *r) for i, r in enumerate(DS.DTA_SYNTHETIC)], ["study", "TP", "FN", "FP", "TN"]), "SIMULATED teaching data (fixed seed) - not real studies.")
    rng = np.random.default_rng(2026); rows = []
    for s in range(1, 9):
        n = 12; base = rng.normal(50, 2); eff = rng.normal(0.08, 0.05)
        for g in ("control", "treated"):
            vials = rng.normal(base * (1 + (eff if g == "treated" else 0)), 3.0, n); rows.append((f"FICT-{s:02d}", g, n, round(float(vials.mean()), 2), round(float(vials.std(ddof=1)), 2)))
    out["fictional_lifespan_vials.csv"] = (w(rows, ["study", "group", "n_vials", "mean_days", "sd_days"]), "FICTIONAL/SIMULATED lifespan summary data (seed 2026). Never mix with real data.")
    rng = np.random.default_rng(42); ipd = []
    for s in range(1, 7):
        n = 50 + 10 * s; b = rng.normal(0.5, 0.2); off = rng.normal(0, 0.5)
        for i in range(n): t = i % 2; ipd.append((s, t, round(float(off + b * t + rng.normal()), 4)))
    out["simulated_ipd.csv"] = (w(ipd, ["study", "trt", "y"]), "SIMULATED individual participant data (seed 42) used in the IPD lesson and benchmark.")
    return out

def datasets_zip():
    buf = io.BytesIO(); readme = ["MetaLab Academy practice datasets", "Published examples come from the R package 'metadat' (check its licence/documentation); SIMULATED/FICTIONAL sets are labelled and must not be mixed with real research data.", ""]
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for name, (txt, prov) in practice_datasets().items(): z.writestr(name, txt); readme.append(f"- {name}: {prov}")
        z.writestr("README.txt", "\n".join(readme))
    return buf.getvalue()

PATHWAY_SHEETS = dict(AS.DISCIPLINE_TRACKS)

def formula_sheet(track=None):
    """Markdown formula sheet for the modules of a discipline track (or all modules if track is None), built from the lessons' formulas."""
    L = lessons.load(); ids = sorted(set((PATHWAY_SHEETS[track]["core"] + PATHWAY_SHEETS[track]["extra"]) if track else L))
    out = [f"# Formula sheet{' - ' + track if track else ''}", "*AI-drafted; check against primary sources; not expert-reviewed.*", ""]
    for n in ids:
        if n in L and L[n]["formulas"]:
            out.append(f"## Module {n}: {L[n]['title']}")
            for f in L[n]["formulas"]: out += [f"**{f['name']}**: `{f['tex']}`", "where " + "; ".join(f"{k} = {v}" for k, v in f["symbols"].items()), ""]
    return "\n".join(out)


# ------------------------------------------------------------------------------------------------ internal learning record
def learning_record(store, today=None):
    today = today or datetime.date.today().isoformat(); L = lessons.load(); done = store.completed(); prof = store.profile()
    ex = [e for e in store.exam_history("final")]; best = max(ex, key=lambda e: e["correct"] / max(1, e["total"])) if ex else None; cap = capstone_status(store.capstone_items())
    lines = [f"# Internal learning record ({today})", "", f"> **{NOT_A_CERTIFICATE}**", "", f"Learner: {prof.get('name') or '(not entered)'}", "",
             f"## Modules marked complete: {len([m for m in done if m in L])} of {len(curriculum.MODULES)} registered ({len(L)} have lessons)", ", ".join(map(str, sorted(m for m in done if m in L))) or "none", ""]
    qa = [(m, store.best_quiz(m)) for m in sorted(L) if store.best_quiz(m)]
    lines += ["## Best self-quiz scores", *[f"- Module {m}: {b['score']}/{b['total']}" for m, b in qa[:200]], "" if qa else "none recorded", ""]
    lines += ["## Final comprehensive assessment (self-administered, unproctored)"]
    if best:
        sec = json.loads(best["by_section"]); lines += [f"- Best attempt: {best['correct']}/{best['total']} ({100*best['correct']/best['total']:.0f}%) on seed {best['seed']}", *[f"  - {k}: {v[0]}/{v[1]}" for k, v in sec.items()]]
    else: lines += ["- not attempted"]
    lines += ["", "## Simulated capstone rubric (self-scored)", f"- Total {cap['total']}/{cap['max']} ({100*cap['pct']:.0f}%); blockers: {', '.join(cap['blockers']) or 'none'}; ready to ask experts to review: {'yes' if cap['ready_for_expert_review'] else 'no'}",
              "", "## What this record does NOT show", "- Any expert review of your work or of the lessons.", "- Competence in conducting a real systematic review (only a real, reviewed review shows that).", "- Anything an employer, journal or funder could rely on."]
    return "\n".join(lines)
